<?php foreach($sections as $section): ?><section id="<?= e((string)($section['anchor_slug']??'')) ?>" class="doc-group"><h2><?= e((string)$section['title']) ?></h2><?php if(!empty($section['body'])): ?><div class="panel"><?= nl2br(e((string)$section['body'])) ?></div><?php endif; ?></section><?php endforeach; ?>
