<?php foreach($documentGroups as $group=>$documents): ?><section class="doc-group"><h2><?= e((string)$group) ?></h2><div class="doc-list"><?php foreach($documents as $doc): ?><div class="doc"><div><strong><?= e((string)($doc['label']?:$doc['title'])) ?></strong><br><small><?= e((string)$doc['document_type']) ?></small></div><a class="btn" href="/documento/<?= (int)$doc['document_id'] ?>/download" target="_blank" rel="noopener">Scarica PDF</a></div><?php endforeach; ?></div></section><?php endforeach; ?>
